(() => {
  'use strict';

  const $ = (selector) => document.querySelector(selector);
  const STORAGE_KEY = 'ciberaula:score:v1';
  const WIN_PERCENT = 75;
  const els = {
    intro: $('#intro'), game: $('#game'), results: $('#results'), start: $('#startBtn'), restart: $('#restartBtn'), print: $('#printBtn'),
    round: $('#roundSize'), timerToggle: $('#timerToggle'), playerName: $('#playerName'), nameError: $('#nameError'), hudPlayer: $('#hudPlayer'),
    snapshot: $('#playerSnapshot'), snapshotLabel: $('#snapshotLabel'), snapshotBar: $('#snapshotBar'), snapshotMeta: $('#snapshotMeta'),
    progressText: $('#progressText'), score: $('#scoreText'), streak: $('#streakText'), timerBox: $('#timerBox'), timer: $('#timerText'), bar: $('#progressBar'),
    channel: $('#channelBadge'), caseId: $('#caseId'), sender: $('#sender'), subject: $('#subject'), message: $('#message'), inspect: $('#inspectBtn'),
    details: $('#details'), link: $('#linkValue'), attachment: $('#attachmentValue'), hint: $('#hint'), hintBtn: $('#hintBtn'),
    phishing: $('#phishingBtn'), legit: $('#legitBtn'), feedback: $('#feedback'), feedbackTitle: $('#feedbackTitle'), feedbackText: $('#feedbackText'),
    signals: $('#signals'), action: $('#actionText'), next: $('#nextBtn'), ring: $('#resultRing'), percent: $('#percentText'), resultTitle: $('#resultTitle'),
    resultMessage: $('#resultMessage'), resultPlayer: $('#resultPlayer'), victoryNotice: $('#victoryNotice'), correct: $('#correctText'), wrong: $('#wrongText'),
    finalScore: $('#finalScoreText'), review: $('#review'), sound: $('#soundBtn'), full: $('#fullBtn'), scoreBtn: $('#scoreBtn'),
    resultScoreBtn: $('#resultScoreBtn'), scorePanel: $('#scorePanel'), closeScoreBtn: $('#closeScoreBtn'), scoreList: $('#scoreList'),
    emptyScore: $('#emptyScore'), scaleLegend: $('#scoreScaleLegend')
  };

  let state = {
    questions: [], index: 0, score: 0, streak: 0, correct: 0, wrong: [], answered: false, hint: false,
    timerEnabled: true, time: 45, tick: null, sound: true, player: ''
  };
  let lastFocus = null;

  const safeText = (element, value) => { if (element) element.textContent = String(value ?? ''); };
  const normalizeName = (name) => name.trim().replace(/\s+/g, ' ').slice(0, 40);
  const playerKey = (name) => normalizeName(name).toLocaleLowerCase('es');
  const validQuestion = (q) => q && q.id && q.canal && q.remitente && q.asunto && q.mensaje &&
    ['phishing', 'legitimo'].includes(q.resultado) && Array.isArray(q.senales);
  const shuffle = (items) => {
    const copy = [...items];
    for (let index = copy.length - 1; index > 0; index -= 1) {
      const random = Math.floor(Math.random() * (index + 1));
      [copy[index], copy[random]] = [copy[random], copy[index]];
    }
    return copy;
  };

  const loadScore = () => {
    try {
      const parsed = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
    } catch (_) { return {}; }
  };
  const saveScore = (score) => {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(score)); return true; }
    catch (_) { return false; }
  };
  const getPlayerRecord = (name) => {
    const record = loadScore()[playerKey(name)];
    return record || { name: normalizeName(name), games: 0, wins: 0, totalPoints: 0, bestPercent: 0 };
  };
  const registerResult = (name, percent, points) => {
    const all = loadScore();
    const key = playerKey(name);
    const previous = all[key] || { name, games: 0, wins: 0, totalPoints: 0, bestPercent: 0 };
    const won = percent >= WIN_PERCENT;
    all[key] = {
      name: normalizeName(name), games: Number(previous.games || 0) + 1, wins: Number(previous.wins || 0) + (won ? 1 : 0),
      totalPoints: Number(previous.totalPoints || 0) + points, bestPercent: Math.max(Number(previous.bestPercent || 0), percent),
      lastPlayed: new Date().toISOString()
    };
    saveScore(all);
    return { record: all[key], won };
  };
  const milestoneFor = (wins) => Math.max(5, Math.ceil(Math.max(1, wins) / 5) * 5);

  const showScreen = (name) => {
    [els.intro, els.game, els.results].forEach((screen) => screen.classList.remove('active'));
    els[name].classList.add('active');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };
  const beep = (ok = true) => {
    if (!state.sound) return;
    try {
      const Audio = window.AudioContext || window.webkitAudioContext;
      const context = new Audio(); const oscillator = context.createOscillator(); const gain = context.createGain();
      oscillator.connect(gain); gain.connect(context.destination); oscillator.frequency.value = ok ? 640 : 180;
      gain.gain.setValueAtTime(0.08, context.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, context.currentTime + 0.18);
      oscillator.start(); oscillator.stop(context.currentTime + 0.18);
    } catch (_) { /* El audio es opcional. */ }
  };
  const stopTimer = () => { clearInterval(state.tick); state.tick = null; };
  const runTimer = () => {
    stopTimer();
    if (!state.timerEnabled) { els.timerBox.hidden = true; return; }
    state.time = 45; safeText(els.timer, state.time); els.timerBox.hidden = false;
    state.tick = setInterval(() => {
      state.time -= 1; safeText(els.timer, state.time); els.timer.style.color = state.time <= 10 ? 'var(--red)' : '';
      if (state.time <= 0) { stopTimer(); answer('__timeout__'); }
    }, 1000);
  };

  const updateSnapshot = () => {
    const name = normalizeName(els.playerName.value);
    els.nameError.hidden = true;
    if (!name) { els.snapshot.hidden = true; return; }
    const record = getPlayerRecord(name); const milestone = milestoneFor(record.wins);
    els.snapshot.hidden = false; safeText(els.snapshotLabel, `${record.wins} / ${milestone} victorias`);
    els.snapshotBar.style.width = `${Math.min(100, (record.wins / milestone) * 100)}%`;
    safeText(els.snapshotMeta, `${record.games} partidas · ${record.totalPoints} puntos acumulados · mejor resultado ${record.bestPercent}%`);
  };

  const toggleDetails = (forceOpen) => {
    if (!els.game.classList.contains('active')) return;
    const shouldOpen = typeof forceOpen === 'boolean' ? forceOpen : els.details.hidden;
    els.details.hidden = !shouldOpen;
    els.inspect.setAttribute('aria-expanded', String(shouldOpen));
    els.inspect.classList.toggle('is-open', shouldOpen);
    safeText(els.inspect, shouldOpen ? '× OCULTAR DETALLES' : '⌕ INSPECCIONAR DETALLES');
  };

  function start() {
    const name = normalizeName(els.playerName.value);
    if (!name) {
      els.nameError.hidden = false; els.playerName.focus(); els.playerName.setAttribute('aria-invalid', 'true'); return;
    }
    els.playerName.removeAttribute('aria-invalid'); els.nameError.hidden = true;
    const bank = (window.PRUEBAS_PHISHING || []).filter(validQuestion);
    if (!bank.length) { window.alert('No se encontraron pruebas válidas en pruebas.js'); return; }
    const count = els.round.value === 'all' ? bank.length : Math.min(Number(els.round.value), bank.length);
    state = { ...state, questions: shuffle(bank).slice(0, count), index: 0, score: 0, streak: 0, correct: 0, wrong: [], answered: false,
      hint: false, timerEnabled: els.timerToggle.checked, time: 45, tick: null, player: name };
    try { localStorage.setItem('ciberaula:last-player', name); } catch (_) { /* opcional */ }
    safeText(els.hudPlayer, name); showScreen('game'); render();
  }

  function render() {
    stopTimer(); state.answered = false; state.hint = false;
    const question = state.questions[state.index]; const total = state.questions.length;
    safeText(els.progressText, `${state.index + 1} / ${total}`); safeText(els.score, state.score); safeText(els.streak, `${state.streak} 🔥`);
    els.bar.style.width = `${(state.index / total) * 100}%`; safeText(els.channel, question.canal.toUpperCase()); safeText(els.caseId, question.id);
    safeText(els.sender, question.remitente); safeText(els.subject, question.asunto); safeText(els.message, question.mensaje);
    safeText(els.link, question.enlace || 'Sin enlace'); safeText(els.attachment, question.adjunto || 'Ninguno');
    toggleDetails(false); els.hint.hidden = true; safeText(els.hint, ''); els.hintBtn.hidden = false; els.feedback.hidden = true;
    els.feedback.className = 'feedback glass'; [els.phishing, els.legit].forEach((button) => { button.disabled = false; });
    els.timer.style.color = ''; runTimer();
  }

  function useHint() {
    if (state.answered || state.hint) return;
    state.hint = true; state.score = Math.max(0, state.score - 20); safeText(els.score, state.score);
    safeText(els.hint, `PISTA: ${state.questions[state.index].senales[0]}`); els.hint.hidden = false; els.hintBtn.hidden = true; beep(true);
  }
  function answer(choice) {
    if (state.answered) return;
    state.answered = true; stopTimer(); const question = state.questions[state.index]; const ok = choice === question.resultado;
    if (ok) { state.streak += 1; state.correct += 1; state.score += 100 + Math.min((state.streak - 1) * 20, 100); }
    else { state.streak = 0; state.wrong.push(question); }
    safeText(els.score, state.score); safeText(els.streak, `${state.streak} 🔥`); [els.phishing, els.legit].forEach((button) => { button.disabled = true; });
    els.hintBtn.hidden = true; els.feedback.hidden = false; els.feedback.classList.add(ok ? 'correct' : 'wrong');
    safeText(els.feedbackTitle, ok ? '✓ DECISIÓN CORRECTA' : choice === '__timeout__' ? '⌛ TIEMPO AGOTADO' : '✕ DECISIÓN INCORRECTA');
    safeText(els.feedbackText, question.explicacion);
    els.signals.replaceChildren(...question.senales.map((signal) => { const item = document.createElement('li'); item.textContent = signal; return item; }));
    safeText(els.action, question.accion); beep(ok);
    if (!ok) { const card = document.querySelector('.message-card'); card.classList.add('shake'); setTimeout(() => card.classList.remove('shake'), 400); }
    els.feedback.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }
  function next() {
    if (!state.answered) return;
    if (state.index < state.questions.length - 1) { state.index += 1; render(); els.game.scrollIntoView({ behavior: 'smooth' }); }
    else finish();
  }
  function finish() {
    stopTimer(); const total = state.questions.length; const percent = Math.round((state.correct / total) * 100);
    els.bar.style.width = '100%'; safeText(els.percent, `${percent}%`); els.ring.style.setProperty('--p', percent);
    safeText(els.correct, `${state.correct}/${total}`); safeText(els.wrong, state.wrong.length); safeText(els.finalScore, state.score); safeText(els.resultPlayer, state.player);
    let title; let message;
    if (percent >= 90) { title = 'Radar de élite'; message = 'Detectas señales sutiles y verificas antes de actuar.'; }
    else if (percent >= 75) { title = 'Buen detector'; message = 'Tienes criterio sólido. Refuerza las pruebas que fallaste.'; }
    else if (percent >= 60) { title = 'En entrenamiento'; message = 'Reconoces varias señales, pero la presión y la suplantación aún pueden engañarte.'; }
    else { title = 'Alerta roja'; message = 'Necesitas practicar: pausa, inspecciona y verifica siempre por un canal conocido.'; }
    safeText(els.resultTitle, title); safeText(els.resultMessage, message);
    const saved = registerResult(state.player, percent, state.score);
    els.victoryNotice.className = `victory-notice ${saved.won ? 'won' : 'practice'}`;
    safeText(els.victoryNotice, saved.won ? `VICTORIA REGISTRADA · ${saved.record.wins} ganadas` : `PARTIDA REGISTRADA · alcanza ${WIN_PERCENT}% para sumar una victoria`);
    els.review.replaceChildren();
    if (state.wrong.length) {
      const heading = document.createElement('h3'); heading.textContent = 'Casos para repasar'; els.review.append(heading);
      state.wrong.forEach((question) => { const article = document.createElement('article'); const name = document.createElement('b'); const text = document.createElement('p');
        name.textContent = `${question.id} · ${question.asunto}`; text.textContent = question.explicacion; article.append(name, text); els.review.append(article); });
    }
    showScreen('results');
  }

  const renderScore = () => {
    const records = Object.values(loadScore()).filter((record) => record && record.name).sort((a, b) => (b.wins - a.wins) || (b.totalPoints - a.totalPoints));
    els.scoreList.replaceChildren(); els.emptyScore.hidden = records.length > 0;
    const maxWins = Math.max(0, ...records.map((record) => Number(record.wins || 0))); const milestone = milestoneFor(maxWins);
    els.scaleLegend.replaceChildren();
    for (let value = 0; value <= milestone; value += 1) {
      if (value === 0 || value === milestone || value % 5 === 0) { const tick = document.createElement('span'); tick.textContent = String(value); tick.style.left = `${(value / milestone) * 100}%`; els.scaleLegend.append(tick); }
    }
    records.forEach((record, index) => {
      const row = document.createElement('article'); row.className = 'score-row';
      const rank = document.createElement('span'); rank.className = 'score-rank'; rank.textContent = String(index + 1).padStart(2, '0');
      const body = document.createElement('div'); body.className = 'score-body';
      const top = document.createElement('div'); top.className = 'score-row-top'; const name = document.createElement('strong'); name.textContent = record.name;
      const wins = document.createElement('b'); wins.textContent = `${record.wins || 0} ${Number(record.wins) === 1 ? 'victoria' : 'victorias'}`; top.append(name, wins);
      const track = document.createElement('div'); track.className = 'victory-scale'; track.setAttribute('aria-label', `${record.name}: ${record.wins || 0} de ${milestone} victorias en la escala`);
      const fill = document.createElement('i'); fill.style.width = `${Math.min(100, (Number(record.wins || 0) / milestone) * 100)}%`; track.append(fill);
      const meta = document.createElement('small'); meta.textContent = `${record.games || 0} partidas · ${record.totalPoints || 0} puntos · mejor ${record.bestPercent || 0}%`;
      body.append(top, track, meta); row.append(rank, body); els.scoreList.append(row);
    });
  };
  const openScore = () => {
    lastFocus = document.activeElement; renderScore(); els.scorePanel.hidden = false; els.scorePanel.setAttribute('aria-hidden', 'false');
    document.body.classList.add('modal-open'); els.closeScoreBtn.focus(); history.replaceState(null, '', '#score');
  };
  const closeScore = () => {
    els.scorePanel.hidden = true; els.scorePanel.setAttribute('aria-hidden', 'true'); document.body.classList.remove('modal-open');
    if (location.hash === '#score') history.replaceState(null, '', location.pathname + location.search); lastFocus?.focus();
  };

  els.start.addEventListener('click', start); els.restart.addEventListener('click', () => { showScreen('intro'); updateSnapshot(); els.playerName.focus(); });
  els.print.addEventListener('click', () => window.print()); els.inspect.addEventListener('click', () => toggleDetails()); els.hintBtn.addEventListener('click', useHint);
  els.phishing.addEventListener('click', () => answer('phishing')); els.legit.addEventListener('click', () => answer('legitimo')); els.next.addEventListener('click', next);
  els.playerName.addEventListener('input', updateSnapshot); els.playerName.addEventListener('keydown', (event) => { if (event.key === 'Enter') start(); });
  [els.scoreBtn, els.resultScoreBtn].forEach((button) => button.addEventListener('click', openScore)); els.closeScoreBtn.addEventListener('click', closeScore);
  els.scorePanel.addEventListener('click', (event) => { if (event.target === els.scorePanel) closeScore(); });
  els.sound.addEventListener('click', () => { state.sound = !state.sound; safeText(els.sound, state.sound ? '🔊' : '🔇'); els.sound.setAttribute('aria-label', state.sound ? 'Desactivar sonido' : 'Activar sonido'); });
  els.full.addEventListener('click', () => { document.fullscreenElement ? document.exitFullscreen() : document.documentElement.requestFullscreen?.(); });
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape' && !els.scorePanel.hidden) { closeScore(); return; }
    if (event.target.matches('input,select,textarea,button')) return;
    const key = event.key.toLowerCase(); if (key === 'i') toggleDetails();
    if (els.game.classList.contains('active') && !state.answered && key === 'p') answer('phishing');
    if (els.game.classList.contains('active') && !state.answered && key === 'l') answer('legitimo');
    if (els.game.classList.contains('active') && state.answered && key === 'n') next();
  });
  window.addEventListener('beforeunload', stopTimer);

  try { els.playerName.value = localStorage.getItem('ciberaula:last-player') || ''; } catch (_) { /* opcional */ }
  updateSnapshot();
  if (location.hash === '#score') window.setTimeout(openScore, 0);
})();
